$AB$ is a diameter, and $C$ is a point on the circle, with $AB = 26$ cm and $AC = 10$ cm. $OM \perp BC$ at $M$. Find $OM$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc, angles, quotes}
\coordinate (O) at (0,0);
\coordinate (A) at (2,0);
\coordinate (B) at (-2,0);
\coordinate (C) at (1.409,1.420);
\coordinate (M) at (-0.296,0.710);
\draw (O) circle (2);
\fill (O) circle (1.5pt) node[below] {$O$};
\draw (A) -- (B) node[pos=0.75, below, fill=white, inner sep=1pt] {$26\text{ cm}$};
\draw (A) -- (C) node[midway, above right, fill=white, inner sep=1pt] {$10\text{ cm}$};
\draw (B) -- (C);
\draw (O) -- (M);
\node[right] at (A) {$A$};
\node[left] at (B) {$B$};
\node[above right] at (C) {$C$};
\node[left] at (M) {$M$};
\coordinate (Ca) at ($(C)!0.3cm!(A)$);
\coordinate (Cb) at ($(C)!0.3cm!(B)$);
\draw (Ca) -- ($(Ca)+(Cb)-(C)$) -- (Cb);
\coordinate (Ma) at ($(M)!0.3cm!(B)$);
\coordinate (Mb) at ($(M)!0.3cm!(O)$);
\draw (Ma) -- ($(Ma)+(Mb)-(M)$) -- (Mb);
\end{tikzpicture}
[/tikz]

$AB = CD$ (equal chords) and $\angle COD = 76^{\circ}$. $E$ lies on the major arc $AB$. Find $\angle AEB$.
[tikz]\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc, decorations.markings, angles, quotes}
\usetikzlibrary{decorations.markings}
\tikzset{
  tickmark/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (0pt,-4pt) -- (0pt,4pt);}}}},
  tickmark2/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (-2pt,-4pt) -- (-2pt,4pt);
                               \draw[black] (2pt,-4pt) -- (2pt,4pt);}}}},
  tickmark3/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (-3pt,-4pt) -- (-3pt,4pt);
                               \draw[black] (0pt,-4pt) -- (0pt,4pt);
                               \draw[black] (3pt,-4pt) -- (3pt,4pt);}}}},
}
\coordinate (O) at (0,0);
\draw (O) circle (2);
\fill (O) circle (1.5pt) node[right] {$O$};
\coordinate (A) at (-1.732,1);
\coordinate (B) at (0.551,1.923);
\coordinate (C) at (1,-1.732);
\coordinate (D) at (-1.439,-1.389);
\coordinate (E) at (1.879,0.684);
\node[above left] at (A) {$A$};
\node[above right] at (B) {$B$};
\node[below right] at (C) {$C$};
\node[below left] at (D) {$D$};
\node[above] at (E) {$E$};
\draw[tickmark] (A) -- (B);
\draw[tickmark] (C) -- (D);
\draw (O) -- (C);
\draw (O) -- (D);
\draw (E) -- (A);
\draw (E) -- (B);
\pic[draw, "76^{\circ}", angle radius=0.55cm, angle eccentricity=2] {angle = D--O--C};
\pic[draw, "x", angle radius=0.4cm, angle eccentricity=2] {angle = B--E--A};
\end{tikzpicture}
[/tikz]

$ABCD$ is a cyclic quadrilateral, and $AC$ is a diameter. $\angle BAC = 28^{\circ}$. Find $\angle BCA$.
[tikz]\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc, angles, quotes}
\coordinate (O) at (0,0);
\coordinate (A) at (1.732,1);
\coordinate (B) at (-1.798,0.877);
\coordinate (C) at (-1.732,-1);
\coordinate (D) at (0.209,-1.989);
\draw (A) -- (B);
\draw (B) -- (C);
\draw (C) -- (D);
\draw (D) -- (A);
\draw (A) -- (C);
\draw (O) circle (2);
\node[left] at (A) {$A$};
\node[above] at (B) {$B$};
\node[right] at (C) {$C$};
\node[below] at (D) {$D$};
\pic[draw, "28^{\circ}", angle radius=0.4cm, angle eccentricity=2] {angle = B--A--C};
\pic[draw, "33^{\circ}", angle radius=0.4cm, angle eccentricity=2] {angle = C--A--D};
\end{tikzpicture}
[/tikz]

